/// Provider-neutral transfer/local records. Remote adapters translate their
/// database SDK objects into these maps before invoking a mapper.
class EntityDto {const EntityDto(this.values);final Map<String,Object?> values;}
class LocalEntity {const LocalEntity(this.values);final Map<String,Object?> values;}
abstract interface class EntityMapper<D> {D fromDto(EntityDto dto);EntityDto toDto(D domain);LocalEntity toLocal(D domain);D fromLocal(LocalEntity local);}
class MappedEntity {const MappedEntity({required this.id,required this.fields});final String id;final Map<String,Object?> fields;}
class StandardEntityMapper implements EntityMapper<MappedEntity>{const StandardEntityMapper(this.entityType);final String entityType;@override MappedEntity fromDto(EntityDto dto)=>_read(dto.values);@override MappedEntity fromLocal(LocalEntity local)=>_read(local.values);MappedEntity _read(Map<String,Object?> value)=>MappedEntity(id:value['id']! as String,fields:Map.unmodifiable({...value}..remove('id')..remove('entityType')));Map<String,Object?> _write(MappedEntity value)=>{'entityType':entityType,'id':value.id,...value.fields};@override EntityDto toDto(MappedEntity domain)=>EntityDto(_write(domain));@override LocalEntity toLocal(MappedEntity domain)=>LocalEntity(_write(domain));}
abstract final class EntityMappers {static const user=StandardEntityMapper('user');static const seller=StandardEntityMapper('seller');static const product=StandardEntityMapper('product');static const sellerProduct=StandardEntityMapper('sellerProduct');static const watchlistItem=StandardEntityMapper('watchlistItem');static const productAlert=StandardEntityMapper('productAlert');static const productRequest=StandardEntityMapper('productRequest');static const moderationCase=StandardEntityMapper('moderationCase');}
